static void atl1e_rx_mode ( struct net_device * netdev , netdev_features_t features ) { struct atl1e_adapter * adapter = netdev_priv ( netdev ) ; u32 mac_ctrl_data ; netdev_dbg ( adapter -> netdev , "%s\n" , __func__ ) ; atl1e_irq_disable ( adapter ) ; mac_ctrl_data = AT_READ_REG ( & adapter -> hw , REG_MAC_CTRL ) ; __atl1e_rx_mode ( features , & mac_ctrl_data ) ; AT_WRITE_REG ( & adapter -> hw , REG_MAC_CTRL , mac_ctrl_data ) ; atl1e_irq_enable ( adapter ) ; } 